from cryptography.hazmat.primitives import serialization

key_pem = """-----BEGIN PRIVATE KEY-----

-----END PRIVATE KEY-----"""

try:
    private_key = serialization.load_pem_private_key(
        key_pem.encode(),
        password=None,
    )
    print("Private key loaded successfully.")
except ValueError as e:
    print(f"Error: {e}")
